begin;
create function pg_temp.fail_review_event() returns trigger language plpgsql as $$
begin
 if new.kind='review.no_change' and current_setting('noreon.test_review_failure',true)='on' then raise exception 'fictional forced review failure';end if;
 return new;
end $$;
create trigger fictional_review_failure before insert on public.workspace_activity for each row execute function pg_temp.fail_review_event();
do $$
declare admin_id uuid:=gen_random_uuid();c uuid:=gen_random_uuid();d uuid:=gen_random_uuid();cl uuid:=gen_random_uuid();s jsonb;w jsonb;draft jsonb;rev integer;ev bigint;t uuid;published jsonb;care jsonb;before_case jsonb;before_task jsonb;before_events bigint;
begin
 insert into auth.users(id) values(d),(admin_id);
 insert into public.workspace_staff(user_id,role,display_name) values(admin_id,'admin','Fictional notification admin');
 insert into public.workspace_clinics(id,name) values(cl,'Fictional completion clinic');
 insert into public.workspace_staff(user_id,role,display_name,clinic_id) values(d,'doctor','Fictional doctor',cl);
 draft:=jsonb_build_object('explanation','Reviewed','instructions','Fictional plan','followUp','','medicationName','','medicationDose','','medicationInstructions','','medicationTimes','[]'::jsonb);
 w:=jsonb_build_object('revision',0,'startedAt',now(),'tests','[]'::jsonb,'receivedTestIds','[]'::jsonb,'allResultsAt',now(),'consultation','not-required','draft',draft,'draftSaved',false,'publication',null);
 s:=jsonb_build_object('userId',c,'expiresAt',extract(epoch from now()+interval '1 day')*1000,'state',jsonb_build_object('consentAccepted',true,'assessment',jsonb_build_object('completedAt',now(),'urgentRule',null)));
 perform public.workspace_create_case(c,s,d);rev:=public.workspace_initialize_workflow(c,0,w);
 select evidence_revision into ev from public.workspace_cases where id=c;
 rev:=public.workspace_save_review_draft(c,d,rev,ev,draft);
 rev:=public.workspace_publish_review(c,d,rev,ev);
 select state#>'{workflow,publication}',state->'care' into published,care from public.workspace_cases where id=c;
 if published->'reviewCoverage' is null or not exists(select 1 from public.workspace_review_tasks where case_id=c and status='completed' and outcome='published') then raise exception 'TEST: publication did not complete an attributed task';end if;
 t:=public.workspace_reconcile_review_task(c,true,'questionnaire');
 begin perform public.workspace_complete_review_no_change(c,d,rev-1,t,ev,'Reviewed');raise exception 'TEST: stale case accepted';exception when others then if sqlerrm not like '%conflict%' then raise;end if;end;
 begin perform public.workspace_complete_review_no_change(c,d,rev,t,ev,E'\t\n');raise exception 'TEST: whitespace-only review accepted';exception when others then if sqlerrm like 'TEST:%' then raise;end if;end;
 update public.workspace_staff set active=false where user_id=d;
 begin perform public.workspace_complete_review_no_change(c,d,rev,t,ev,'Reviewed');raise exception 'TEST: inactive doctor completed review';exception when others then if sqlerrm not like '%active GP%' then raise;end if;end;
 update public.workspace_staff set active=true where user_id=d;
 rev:=public.workspace_assign_case(c,rev,null);
 if not exists(select 1 from public.workspace_review_tasks where id=t and status='open' and owner_id is null) then raise exception 'TEST: assignment did not clear task owner';end if;
 begin perform public.workspace_complete_review_no_change(c,d,rev,t,ev,'Reviewed');raise exception 'TEST: unassigned doctor completed review';exception when others then if sqlerrm not like '%active GP%' then raise;end if;end;
 rev:=public.workspace_assign_case(c,rev,d);
 select to_jsonb(x) into before_case from public.workspace_cases x where id=c;
 select to_jsonb(x) into before_task from public.workspace_review_tasks x where id=t;
 select count(*) into before_events from public.workspace_activity where case_id=c;
 perform set_config('noreon.test_review_failure','on',true);
 begin perform public.workspace_complete_review_no_change(c,d,rev,t,ev,'Reviewed');raise exception 'TEST: injected failure was ignored';exception when others then if sqlerrm<>'fictional forced review failure' then raise;end if;end;
 perform set_config('noreon.test_review_failure','off',true);
 if before_case is distinct from (select to_jsonb(x) from public.workspace_cases x where id=c) or before_task is distinct from (select to_jsonb(x) from public.workspace_review_tasks x where id=t) or before_events<>(select count(*) from public.workspace_activity where case_id=c) then raise exception 'TEST: failed review left partial state';end if;
 rev:=public.workspace_complete_review_no_change(c,d,rev,t,ev,'Reviewed fictional evidence; no plan change.');
 if not exists(select 1 from public.workspace_cases where id=c and state#>'{workflow,publication}'=published and state->'care'=care) then raise exception 'TEST: no-change altered approved care';end if;
 if not exists(select 1 from public.workspace_review_tasks where id=t and status='completed' and outcome='no-change' and completed_by=d and completed_by_label='Fictional doctor') then raise exception 'TEST: missing no-change attribution';end if;
 insert into public.workspace_case_reports(case_id,id,record,approval) values(c,'10000000-0000-4000-8000-000000000001',jsonb_build_object('id','10000000-0000-4000-8000-000000000001','revision',1),jsonb_build_object('revision',1));
 select revision,evidence_revision into rev,ev from public.workspace_cases where id=c;
 select id into t from public.workspace_review_tasks where case_id=c and status='open';
 if t is null then raise exception 'TEST: report did not open a review task';end if;
 rev:=public.workspace_save_review_draft(c,d,rev,ev,draft);
 begin perform public.workspace_complete_review_no_change(c,d,rev,t,ev,'Reviewed');raise exception 'TEST: unreleased report accepted';exception when others then if sqlerrm not like '%Publish%' then raise;end if;end;
 rev:=public.workspace_publish_review(c,d,rev,ev);
 delete from public.workspace_case_reports where case_id=c and id='10000000-0000-4000-8000-000000000001';
 select revision,evidence_revision into rev,ev from public.workspace_cases where id=c;
 select id into t from public.workspace_review_tasks where case_id=c and status='open';
 if t is null then raise exception 'TEST: report deletion did not reopen review';end if;
 rev:=public.workspace_save_review_draft(c,d,rev,ev,draft);
 begin perform public.workspace_complete_review_no_change(c,d,rev,t,ev,'Reviewed');raise exception 'TEST: deleted report coverage accepted';exception when others then if sqlerrm not like '%Publish%' then raise;end if;end;
 if not exists(select 1 from public.workspace_notifications n join public.workspace_activity a on a.id=n.event_id where a.case_id=c and a.kind='plan.published' and n.recipient='staff:'||admin_id) then raise exception 'TEST: primary publication notification missing';end if;
 if exists(select 1 from public.workspace_notifications n join public.workspace_activity a on a.id=n.event_id where a.case_id=c and a.kind='review.published') then raise exception 'TEST: review publication generated duplicate notifications';end if;
 if public.workspace_case_snapshot(c)->'reviewTasks' is null then raise exception 'TEST: snapshot missing tasks';end if;
end $$;
rollback;
